<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Compress Online','description'=>'Save a PDF as a new optimized document directly in your browser.','url'=>'https://smarttoolz.in/tools/pdf-compress/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PDF COMPRESS</span><h1>PDF Compressor</h1><p>Load a PDF and create a clean copy in your browser.</p></section><section class="tool-workspace"><div class="tool-panel"><label>PDF file<input id="f" type="file" accept="application/pdf"></label><button id="go" class="tool-btn">Create PDF Copy</button><p id="out"></p></div></section></main><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script>(()=>{const $=id=>document.getElementById(id);$('go').onclick=async()=>{let f=$('f').files[0];if(!f){$('out').textContent='Choose a PDF.';return}try{let p=await PDFLib.PDFDocument.load(await f.arrayBuffer()),b=new Blob([await p.save()],{type:'application/pdf'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='compressed.pdf';a.click();$('out').textContent='PDF processed successfully.'}catch(e){$('out').textContent='Could not process this PDF.'}}})();</script><?php smarttoolz_tool_page_end(); ?>